bash: cat > workspace_audit.json << 'EOF'
{
  "audit_metadata": {
    "generated_at": "2024-05-20T00:00:00Z",
    "purpose": "Document conflicts and discrepancies between workspace files for ticket creation",
    "resolution_policy": "specs/requirements.yaml and v2.0 architecture notes are authoritative"
  },
  "discrepancies": [
    {
      "id": "DISC-001",
      "title": "Cache max_size_mb mismatch",
      "description": "The maximum cache size is specified differently in the requirements spec versus the cache configuration file.",
      "files_in_conflict": [
        {
          "path": "specs/requirements.yaml",
          "value": "512 MB",
          "location": "caching.max_size_mb"
        },
        {
          "path": "config/cache_config.yaml",
          "value": "256 MB",
          "location": "cache.max_size_mb"
        }
      ],
      "resolution": "Use 512 MB from requirements.yaml as the authoritative source. Update config/cache_config.yaml to match.",
      "action_required": "Update config/cache_config.yaml cache.max_size_mb to 512",
      "severity": "medium"
    },
    {
      "id": "DISC-002",
      "title": "AAC max_bitrate unit error in CSV",
      "description": "The codec support matrix CSV has an incorrect value for AAC max bitrate - appears to be a unit conversion error (0.512 instead of 512).",
      "files_in_conflict": [
        {
          "path": "specs/requirements.yaml",
          "value": "512 kbps",
          "location": "codec_support.supported_codecs.aac.max_bitrate_kbps"
        },
        {
          "path": "data/codec_support_matrix.csv",
          "value": "0.512",
          "location": "Row: aac, Column: max_bitrate"
        }
      ],
      "resolution": "512 kbps is correct per requirements.yaml. The CSV value 0.512 appears to be incorrectly treating the value as Mbps or has a decimal error. Update CSV to 512.",
      "action_required": "Update data/codec_support_matrix.csv AAC row max_bitrate column from 0.512 to 512",
      "severity": "medium"
    },
    {
      "id": "DISC-003",
      "title": "cpal version insufficient for PipeWire support",
      "description": "The Cargo.toml reference specifies cpal 0.13, but the platform matrix correctly identifies that cpal 0.15+ is required for PipeWire backend support.",
      "files_in_conflict": [
        {
          "path": "deps/Cargo.toml.reference",
          "value": "0.13",
          "location": "dependencies.cpal.version"
        },
        {
          "path": "specs/platform_matrix.toml",
          "value": "0.15+ required for pipewire support",
          "location": "dependencies.cpal.notes"
        }
      ],
      "resolution": "Use cpal 0.15+ as specified in platform_matrix.toml. This is a blocking issue for Linux/PipeWire support.",
      "action_required": "Update deps/Cargo.toml.reference cpal dependency from \"0.13\" to \"0.15\"",
      "severity": "high"
    },
    {
      "id": "DISC-004",
      "title": "Ring buffer capacity explanation inconsistency",
      "description": "The threading model and architecture notes express ring buffer capacity differently, potentially causing confusion.",
      "files_in_conflict": [
        {
          "path": "specs/threading_model.yaml",
          "value": "65536 samples (16384 frames * 2 channels * 2 safety margin)",
          "location": "threads.audio_thread.buffer_config.ring_buffer_capacity_frames"
        },
        {
          "path": "docs/architecture_notes.md",
          "value": "4096 frames × 2 channels × 4 bytes × 32 buffers",
          "location": "Memory Budget section, ring buffer row"
        }
      ],
      "resolution": "These are mathematically equivalent but poorly explained. 65536 samples = 32768 frames stereo = 8x the 4096-frame callback buffer. The architecture notes calculation is incorrect (4096*2*4*32 ≠ 65536). The threading_model.yaml calculation is correct (16384*2*2 = 65536).",
      "action_required": "Clarify ring buffer calculation in docs/architecture_notes.md. Current math is wrong.",
      "severity": "low"
    },
    {
      "id": "DISC-005",
      "title": "WAV codec max sample rate not specified in requirements",
      "description": "The requirements.yaml does not specify sample rate support for WAV codec, while the CSV matrix indicates 48kHz max.",
      "files_in_conflict": [
        {
          "path": "specs/requirements.yaml",
          "value": "Not specified",
          "location": "codec_support.supported_codecs.wav - no sample rate field"
        },
        {
          "path": "data/codec_support_matrix.csv",
          "value": "8000;11025;16000;22050;32000;44100;48000;88200;96000",
          "location": "Row: wav, Column: supported_sample_rates"
        }
      ],
      "resolution": "WAV is an uncompressed format and can support any sample rate. The CSV shows up to 96kHz which is practical. Sample tracks include WAV at 96kHz (Unfinished Stories) and 44.1kHz. Recommend aligning requirements.yaml to match CSV.",
      "action_required": "Add supported_sample_rates field to specs/requirements.yaml codec_support.supported_codecs.wav entry",
      "severity": "low"
    },
    {
      "id": "DISC-006",
      "title": "FLAC container formats incomplete in CSV",
      "description": "The CSV lists FLAC supporting 'flac;ogg' containers, but Ogg FLAC is non-standard and rarely used.",
      "files_in_conflict": [
        {
          "path": "data/codec_support_matrix.csv",
          "value": "flac;ogg",
          "location": "Row: flac, Column: container_formats"
        }
      ],
      "resolution": "FLAC is typically only in .flac containers. Ogg FLAC exists but is extremely rare. Consider removing 'ogg' from container formats or documenting this is symphonia-specific support.",
      "action_required": "Review and clarify FLAC container support in data/codec_support_matrix.csv",
      "severity": "low"
    }
  ],
  "summary": {
    "total_discrepancies": 6,
    "by_severity": {
      "high": 1,
      "medium": 2,
      "low": 3
    },
    "critical_actions": [
      "Bump cpal version to 0.15+ in deps/Cargo.toml.reference",
      "Update cache max_size_mb to 512 in config/cache_config.yaml",
      "Fix AAC max_bitrate value in data/codec_support_matrix.csv"
    ]
  }
}
EOF
echo "workspace_audit.json created successfully"
